def parse_scenario(scenario, declared, link_pairs):
    """Validate a failure scenario against the original topology.

    Returns a list of (time, action, target) tuples (the target is a node
    name or a canonical link pair), or None if the scenario is malformed.
    Times must be positive integers strictly increasing; every referenced
    node or link must exist in the original topology.
    """
    if not isinstance(scenario, dict):
        return None
    events_raw = scenario.get("events")
    if not isinstance(events_raw, list):
        return None

    events = []
    previous_time = 0
    for event in events_raw:
        if not isinstance(event, dict):
            return None
        time = event.get("time")
        action = event.get("action")
        if isinstance(time, bool) or not isinstance(time, int):
            return None
        if time <= previous_time:
            return None
        if not isinstance(action, str):
            return None
        if action in {"node-down", "node-up"}:
            node = event.get("node")
            if not isinstance(node, str) or node not in declared:
                return None
            target = node
        elif action in {"link-down", "link-up"}:
            source, target_end = event.get("from"), event.get("to")
            if not isinstance(source, str) or not isinstance(target_end, str):
                return None
            if source not in declared or target_end not in declared:
                return None
            pair = (source, target_end) if source < target_end else (target_end, source)
            if pair not in link_pairs:
                return None
            target = pair
        else:
            return None
        events.append((time, action, target))
        previous_time = time
    return events

